/bin/bash -lc "python - <<'PY'
import json, urllib.request
for repo in ['numpy','python']:
 u=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?onlyActiveTags=true&limit=100'
 try:
  with urllib.request.urlopen(u) as f: d=json.load(f)
  print(repo)
  for t in d.get('tags',[])[:25]: print(t['name'], t.get('manifest_digest'), t.get('last_modified'))
 except Exception as e: print(type(e).__name__, e)
PY"

